import {TENT,TENT_OBSTACLES,CAMP_REST_TARGETS} from './tent-layout.js';
import {SEAT_CONTACT} from '../world/seating.js';
const fire={x:-12.2,z:26.2};
function seat(id,x,z,owner){const yaw=Math.atan2(fire.x-x,fire.z-z),out={x:x-Math.sin(yaw)*1.08,z:z-Math.cos(yaw)*1.08};return {id:'courtyard.campfire.seat.'+id,roomId:'courtyard',type:'pose',kind:'sit',seating:true,seatTop:.48,anchor:{x,y:.48-SEAT_CONTACT,z,yaw},at:out,exit:{...out,yaw},owner,radius:.72,enterDuration:1.25,label:'모닥불 옆에 앉기',leaveLabel:'모닥불 자리에서 일어나기',text:'따뜻한 불빛과 바다를 바라보며 쉬어요.'};}
export const PLAZA=Object.freeze({fire,fireRadius:.78,tent:TENT,control:{id:'courtyard.night-plaza',roomId:'courtyard',type:'plazaNight',at:{x:-9.85,z:24},radius:1.1,label:'해변 캠핑 · 모닥불과 불꽃놀이'},seats:[seat('dormi',-8.8,27.5,'dormi'),seat('moa',-15.6,27.5,'moa-playmate'),seat('chinchilla',-12.2,29.8,'chinchilla')],roasting:seat('roast',-10.4,26.9,'activity'),launch:{x:-12.2,z:40.3,y:-.15},visitors:[{id:'moa-playmate',home:{x:-17.8,z:28.8},seatId:'courtyard.campfire.seat.moa',radius:.48},{id:'chinchilla',home:{x:-8.6,z:30.6},seatId:'courtyard.campfire.seat.chinchilla',radius:.5}]});
export function plazaCollision(room){return {...room,obstacles:[...room.obstacles.filter(o=>o.id!=='courtyard.campfire'&&o.id!=='courtyard.campsite.tent'&&!TENT_OBSTACLES.some(t=>t.id===o.id)&&!PLAZA.seats.some(s=>s.id===o.id)),...TENT_OBSTACLES,{id:'courtyard.campfire',...fire,hx:.78,hz:.78},...PLAZA.seats.map(s=>({id:s.id,x:s.anchor.x,z:s.anchor.z,yaw:s.anchor.yaw,hx:.6,hz:.32}))]};}
export const PLAZA_TARGETS=[PLAZA.control,PLAZA.seats[0],...CAMP_REST_TARGETS];
